pub const fn mel_p1(_: &Ctx) -> f32 {
    0f32
}

pub const fn mel_p2(ctx: &Ctx) -> f32 {
    8f32 + 0.04 * ctx.ability_power + 22f32 * (-1f32 + ctx.level) / 17f32
}

pub const fn mel_p3(ctx: &Ctx) -> f32 {
    0.36 * ctx.ability_power
}

pub const fn mel_p4(ctx: &Ctx) -> f32 {
    10f32 * (4f32 + 0.01 * ctx.ability_power + ctx.level)
}

pub const fn mel_p5(ctx: &Ctx) -> f32 {
    0.05 * ctx.ability_power
}

pub const fn mel_p6(ctx: &Ctx) -> f32 {
    0.0075 * ctx.ability_power
}

pub const fn mel_q1(ctx: &Ctx) -> f32 {
    5f32 * (12f32 + 0.11 * ctx.ability_power + 5f32 * (-1f32 + ctx.q_level))
}

pub const fn mel_q2(ctx: &Ctx) -> f32 {
    5f32 + 0.05 * ctx.ability_power + 2f32 * (-1f32 + ctx.q_level)
}

pub const fn mel_q3(ctx: &Ctx) -> f32 {
    (match ctx.q_level as u8 {
        ..=1 => 85f32,
        2 => 127f32,
        3 => 173f32,
        4 => 223f32,
        5.. => 277f32,
    }) + ctx.ability_power * (0.8 + 0.05 * (-1f32 + ctx.q_level))
}

pub const fn mel_w1(ctx: &Ctx) -> f32 {
    0.0005 * ctx.ability_power
        + ctx.steelcaps_effect * (0.4 + 0.05 * (-1f32 + ctx.w_level))
}

pub const fn mel_w2(ctx: &Ctx) -> f32 {
    0.00035 * ctx.ability_power
        + ctx.steelcaps_effect * (0.28 + 0.035 * (-1f32 + ctx.w_level))
}

pub const fn mel_e1(ctx: &Ctx) -> f32 {
    2f32 * (4f32 + 0.02 * ctx.ability_power + 3f32 * (-1f32 + ctx.e_level))
}

pub const fn mel_e2(ctx: &Ctx) -> f32 {
    2f32 + 0.01 * ctx.ability_power + 1.5 * (-1f32 + ctx.e_level)
}

pub const fn mel_e3(ctx: &Ctx) -> f32 {
    15f32
        * (4f32
            + 0.046666666667 * ctx.ability_power
            + 3f32 * (-1f32 + ctx.e_level))
}

pub const fn mel_r1(ctx: &Ctx) -> f32 {
    10f32 * ctx.r_level
}

pub const fn mel_r2(ctx: &Ctx) -> f32 {
    125f32
        + 0.3 * ctx.ability_power
        + 75f32 * (-1f32 + ctx.r_level)
        + ctx.stacks
            * (4f32 + 0.04 * ctx.ability_power + 1.5 * (-1f32 + ctx.r_level))
}

pub const fn mel_r3(ctx: &Ctx) -> f32 {
    ctx.r_level
}

