pub const fn nidalee_q1(ctx: &Ctx) -> f32 {
    227.5 + 1.625 * ctx.ability_power + 65f32 * (-1f32 + ctx.q_level)
}

pub const fn nidalee_q2(ctx: &Ctx) -> f32 {
    70f32 + 20f32 * (-1f32 + ctx.r_level) + ctx.ability_power / 2f32
}

pub const fn nidalee_q3(ctx: &Ctx) -> f32 {
    1f32 + 0.25 * (-1f32 + ctx.q_level)
}

pub const fn nidalee_q4(ctx: &Ctx) -> f32 {
    25f32 * (3f32 + ctx.r_level)
}

pub const fn nidalee_q5(ctx: &Ctx) -> f32 {
    (match ctx.r_level as u8 {
        ..=1 => 10f32,
        2 => 67.5,
        3 => 137.5,
        4 => 220f32,
        5.. => 315f32,
    }) + ctx.ability_power * (0.8 + 0.1 * (-1f32 + ctx.r_level))
        + ctx.attack_damage * (1.5 + 0.1875 * (-1f32 + ctx.r_level))
}

pub const fn nidalee_q6(ctx: &Ctx) -> f32 {
    5f32 * (1f32
        + 0.08 * ctx.ability_power
        + 0.15 * ctx.attack_damage
        + 5f32 * (-1f32 + ctx.r_level))
}

pub const fn nidalee_q7(ctx: &Ctx) -> f32 {
    (match ctx.r_level as u8 {
        ..=1 => 13f32,
        2 => 87.75,
        3 => 178.75,
        4 => 286f32,
        5.. => 409.5,
    }) + ctx.ability_power * (1.04 + 0.13 * (-1f32 + ctx.r_level))
        + ctx.attack_damage * (1.95 + 0.24375 * (-1f32 + ctx.r_level))
}

pub const fn nidalee_q8(ctx: &Ctx) -> f32 {
    2f32 * (3.25
        + 0.26 * ctx.ability_power
        + 0.4875 * ctx.attack_damage
        + 16.25 * (-1f32 + ctx.r_level))
}

pub const fn nidalee_w1(ctx: &Ctx) -> f32 {
    10f32 * (0.005 * ctx.ability_power + ctx.w_level)
}

pub const fn nidalee_w2(ctx: &Ctx) -> f32 {
    40f32 * (0.005 * ctx.ability_power + ctx.r_level)
}

pub const fn nidalee_w3(ctx: &Ctx) -> f32 {
    55f32
        + 0.3 * ctx.ability_power
        + 45f32 * (-1f32 + ctx.w_level)
        + ctx.bonus_ad / 2f32
}

pub const fn nidalee_e1(ctx: &Ctx) -> f32 {
    10f32
        * (7f32
            + 0.055 * ctx.ability_power
            + 0.07 * ctx.bonus_ad
            + 6f32 * (-1f32 + ctx.e_level))
}

