pub const fn syndra_p1(ctx: &Ctx) -> f32 {
    ctx.level
}

pub const fn syndra_q1(ctx: &Ctx) -> f32 {
    5f32 * (16f32 + 0.13 * ctx.ability_power + 7f32 * (-1f32 + ctx.q_level))
}

pub const fn syndra_w1(ctx: &Ctx) -> f32 {
    8.4 + 3.6 * (-1f32 + ctx.w_level)
        + ctx.ability_power * (0.092 + 0.006 * (-1f32 + ctx.w_level))
}

pub const fn syndra_w2(ctx: &Ctx) -> f32 {
    10f32 * (7f32 + 0.065 * ctx.ability_power + 3f32 * (-1f32 + ctx.w_level))
}

pub const fn syndra_w3(ctx: &Ctx) -> f32 {
    78.4 + 33.6 * (-1f32 + ctx.w_level)
        + ctx.ability_power * (0.742 + 0.006 * (-1f32 + ctx.w_level))
}

pub const fn syndra_e1(ctx: &Ctx) -> f32 {
    5f32 * (12f32 + 0.12 * ctx.ability_power + 7f32 * (-1f32 + ctx.e_level))
}

pub const fn syndra_r1(ctx: &Ctx) -> f32 {
    40f32 * (1f32 + 0.005 * ctx.ability_power + ctx.r_level)
}

pub const fn syndra_r2(ctx: &Ctx) -> f32 {
    560f32 + 1.4 * ctx.ability_power + 280f32 * (-1f32 + ctx.r_level)
}

pub const fn syndra_r3(ctx: &Ctx) -> f32 {
    120f32 * (1f32 + 0.005 * ctx.ability_power + ctx.r_level)
}

